mod support;
use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};use tower::ServiceExt;use serde_json::{json,Value};
fn request(method:&str,path:&str,token:Option<&str>,body:Body)->Request<Body>{let mut r=Request::builder().method(method).uri(path);if let Some(token)=token{r=r.header("authorization",format!("Bearer {token}"));}r.body(body).unwrap()}
fn select(token:&str,id:&str)->Request<Body>{let mut r=request("POST","/api/speech/model-selection",Some(token),Body::from(json!({"modelId":id}).to_string()));r.headers_mut().insert("content-type","application/json".parse().unwrap());r}
async fn json_response(response:axum::response::Response)->(StatusCode,Value){let status=response.status();(status,serde_json::from_slice(&to_bytes(response.into_body(),1024*1024).await.unwrap()).unwrap())}
#[tokio::test]async fn model_import_admission_and_owner_isolation(){
 let(state,_dir)=support::make_state(true,false).await;let owner=state.db.register_auth_user("models-owner","model test password").await.unwrap().unwrap();let other=state.db.register_auth_user("models-other","model test password").await.unwrap().unwrap();let app=support::router(state.clone());
 assert_eq!(app.clone().oneshot(request("GET","/api/speech/model-library",None,Body::empty())).await.unwrap().status(),StatusCode::UNAUTHORIZED);
 assert_eq!(app.clone().oneshot(request("PUT","/api/speech/model-library?name=test",Some(&owner.token),Body::from("not a model"))).await.unwrap().status(),StatusCode::BAD_REQUEST);
 let mut oversized=request("PUT","/api/speech/model-library?name=test",Some(&owner.token),Body::empty());oversized.headers_mut().insert("content-length","4000000001".parse().unwrap());assert_eq!(app.clone().oneshot(oversized).await.unwrap().status(),StatusCode::BAD_REQUEST);
 let broken=Body::from_stream(futures_util::stream::iter(vec![Ok::<_,std::io::Error>(axum::body::Bytes::from_static(b"partial model")),Err(std::io::Error::other("interrupted upload"))]));assert_eq!(app.clone().oneshot(request("PUT","/api/speech/model-library?name=interrupted",Some(&owner.token),broken)).await.unwrap().status(),StatusCode::BAD_REQUEST);assert_eq!(std::fs::read_dir(state.storage.join("models/whisper")).unwrap().count(),0);
 let mut bytes=vec![0u8;1_000_000];bytes[..4].copy_from_slice(b"lmgg");bytes[4..8].copy_from_slice(&51865u32.to_le_bytes());
 let(status,installed)=json_response(app.clone().oneshot(request("PUT","/api/speech/model-library?name=Test",Some(&owner.token),Body::from(bytes.clone()))).await.unwrap()).await;assert_eq!(status,StatusCode::OK,"{installed}");let id=installed["id"].as_str().unwrap();assert_eq!(id.len(),64);
 assert_eq!(app.clone().oneshot(select(&other.token,id)).await.unwrap().status(),StatusCode::NOT_FOUND);assert_eq!(app.clone().oneshot(select(&owner.token,"../../source")).await.unwrap().status(),StatusCode::BAD_REQUEST);
 let(_,list)=json_response(app.clone().oneshot(request("GET","/api/speech/model-library",Some(&other.token),Body::empty())).await.unwrap()).await;assert!(list["models"].as_array().unwrap().is_empty());
 assert_eq!(app.clone().oneshot(select(&owner.token,id)).await.unwrap().status(),StatusCode::OK);let(_,status)=json_response(app.clone().oneshot(request("GET","/api/speech/models",Some(&owner.token),Body::empty())).await.unwrap()).await;assert_eq!(status["available"],true);assert_eq!(status["model"],"Test");
 let(status,again)=json_response(app.clone().oneshot(request("PUT","/api/speech/model-library?name=Renamed",Some(&owner.token),Body::from(bytes))).await.unwrap()).await;assert_eq!(status,StatusCode::OK);assert_eq!(again["id"],id);
 let entries:Vec<_>=std::fs::read_dir(state.storage.join("models/whisper")).unwrap().map(|e|e.unwrap().path()).collect();assert_eq!(entries.len(),1);assert_eq!(entries[0].extension().unwrap(),"bin");
 let cold=video_kadr_backend::state::AppState::new_with_runtime(state.storage.clone(),2,(*state.tools).clone(),video_kadr_backend::library::Library::load(state.storage.clone()).await,video_kadr_backend::db::Db::open(&state.storage).await.unwrap(),state.encode_budget,2).unwrap();let(_,list)=json_response(support::router(cold).oneshot(request("GET","/api/speech/model-library",Some(&owner.token),Body::empty())).await.unwrap()).await;assert_eq!(list["selectedId"],id);assert_eq!(list["models"][0]["name"],"Renamed");
 std::fs::write(&entries[0],b"corrupt").unwrap();assert_eq!(app.clone().oneshot(select(&owner.token,id)).await.unwrap().status(),StatusCode::BAD_REQUEST);assert_eq!(app.clone().oneshot(select(&owner.token,"configured")).await.unwrap().status(),StatusCode::OK);
}
#[tokio::test]#[ignore="requires explicit local Whisper model and public audio fixture"]async fn imported_learned_model_is_snapshot_for_queued_speech(){
 let model=std::env::var("VIDEO_KADR_TEST_WHISPER_MODEL").unwrap();let audio=std::env::var("VIDEO_KADR_TEST_WHISPER_AUDIO").unwrap();let(state,_dir)=support::make_state(true,false).await;let owner=state.db.register_auth_user("models-real-owner","model test password").await.unwrap().unwrap();let app=support::router(state.clone());
 let bytes=std::fs::read(model).unwrap();let(status,installed)=json_response(app.clone().oneshot(request("PUT","/api/speech/model-library?name=Whisper-tiny-q5",Some(&owner.token),Body::from(bytes))).await.unwrap()).await;assert_eq!(status,StatusCode::OK,"{installed}");let id=installed["id"].as_str().unwrap();assert_eq!(app.clone().oneshot(select(&owner.token,id)).await.unwrap().status(),StatusCode::OK);
 std::fs::copy(audio,state.sources_dir().join("speech.wav")).unwrap();assert!(state.library.add(video_kadr_backend::library::MediaEntry::from_result("source",&json!({"id":"speech","filename":"speech.wav","mediaType":"audio"}))).await);
 let mut direct=request("POST","/api/speech/transcribe",Some(&owner.token),Body::from(json!({"sourceId":"speech","startUs":0,"endUs":11000000,"language":"en"}).to_string()));direct.headers_mut().insert("content-type","application/json".parse().unwrap());let(status,direct)=json_response(app.clone().oneshot(direct).await.unwrap()).await;assert_eq!(status,StatusCode::OK,"{direct}");assert_eq!(direct["modelHash"],id);assert!(!direct["segments"].as_array().unwrap().is_empty());
 let mut permits=vec![];for _ in 0..state.resource_limit(video_kadr_backend::config::resource_classes::ResourceClass::Analysis){permits.push(state.acquire_job_slot(video_kadr_backend::config::resource_classes::ResourceClass::Analysis).await.unwrap());}
 let mut submit=request("POST","/api/speech/jobs",Some(&owner.token),Body::from(json!({"sourceId":"speech","startUs":0,"endUs":11000000,"language":"en"}).to_string()));submit.headers_mut().insert("content-type","application/json".parse().unwrap());let(status,job)=json_response(app.clone().oneshot(submit).await.unwrap()).await;assert_eq!(status,StatusCode::ACCEPTED,"{job}");let job_id=job["jobId"].as_str().unwrap();
 assert_eq!(app.clone().oneshot(select(&owner.token,"configured")).await.unwrap().status(),StatusCode::OK);assert!(state.speech.model.is_none());drop(permits);
 let result=tokio::time::timeout(std::time::Duration::from_secs(30),async{loop{let job=state.get_job(job_id).await.unwrap().unwrap();if matches!(job.status,video_kadr_backend::model::JobStatus::Done|video_kadr_backend::model::JobStatus::Error){break job}tokio::time::sleep(std::time::Duration::from_millis(20)).await;}}).await;let result=match result{Ok(job)=>job,Err(_)=>{let job=state.get_job(job_id).await.unwrap();state.begin_shutdown();let _=state.wait_for_tasks(std::time::Duration::from_secs(5)).await;panic!("speech model job exceeded observation deadline: {job:?}")}};assert_eq!(result.status,video_kadr_backend::model::JobStatus::Done,"{result:?}");let transcript=result.result.unwrap();assert_eq!(transcript["modelHash"],id);assert!(transcript["segments"].as_array().unwrap().iter().filter_map(|s|s["text"].as_str()).collect::<Vec<_>>().join(" ").to_lowercase().contains("country"),"{transcript}");assert_eq!(app.clone().oneshot(select(&owner.token,id)).await.unwrap().status(),StatusCode::OK);let mut permits=vec![];for _ in 0..state.resource_limit(video_kadr_backend::config::resource_classes::ResourceClass::Analysis){permits.push(state.acquire_job_slot(video_kadr_backend::config::resource_classes::ResourceClass::Analysis).await.unwrap());}let mut submit=request("POST","/api/speech/jobs",Some(&owner.token),Body::from(json!({"sourceId":"speech","startUs":0,"endUs":11000000,"language":"en"}).to_string()));submit.headers_mut().insert("content-type","application/json".parse().unwrap());let(status,job)=json_response(app.oneshot(submit).await.unwrap()).await;assert_eq!(status,StatusCode::ACCEPTED);let changed_id=job["jobId"].as_str().unwrap();{use std::io::Write;std::fs::OpenOptions::new().write(true).open(state.storage.join("models/whisper").join(format!("{id}.bin"))).unwrap().write_all(b"x").unwrap();}drop(permits);let failed=tokio::time::timeout(std::time::Duration::from_secs(30),async{loop{let job=state.get_job(changed_id).await.unwrap().unwrap();if matches!(job.status,video_kadr_backend::model::JobStatus::Error|video_kadr_backend::model::JobStatus::Done){break job}tokio::time::sleep(std::time::Duration::from_millis(20)).await;}}).await.unwrap();assert_eq!(failed.status,video_kadr_backend::model::JobStatus::Error);assert_eq!(failed.error_kind.as_deref(),Some("validation"));assert!(failed.result.is_none());
state.begin_shutdown();assert!(state.wait_for_tasks(std::time::Duration::from_secs(5)).await);
}
fn remove(token:&str,id:&str)->Request<Body>{let mut r=request("POST","/api/speech/model-removal",Some(token),Body::from(json!({"modelId":id}).to_string()));r.headers_mut().insert("content-type","application/json".parse().unwrap());r}
#[tokio::test]async fn removal_preserves_other_owner_and_reclaims_last_copy(){
 let(state,_dir)=support::make_state(true,false).await;let a=state.db.register_auth_user("delete-owner-a","model deletion password").await.unwrap().unwrap();let b=state.db.register_auth_user("delete-owner-b","model deletion password").await.unwrap().unwrap();let app=support::router(state.clone());let mut data=vec![0u8;1_000_000];data[..4].copy_from_slice(b"lmgg");data[4..8].copy_from_slice(&51865u32.to_le_bytes());let(_,installed)=json_response(app.clone().oneshot(request("PUT","/api/speech/model-library?name=Shared",Some(&a.token),Body::from(data.clone()))).await.unwrap()).await;let id=installed["id"].as_str().unwrap();let path=state.storage.join("models/whisper").join(format!("{id}.bin"));assert_eq!(app.clone().oneshot(remove(&b.token,id)).await.unwrap().status(),StatusCode::NOT_FOUND);
 assert_eq!(app.clone().oneshot(request("PUT","/api/speech/model-library?name=Shared",Some(&b.token),Body::from(data))).await.unwrap().status(),StatusCode::OK);assert_eq!(app.clone().oneshot(select(&a.token,id)).await.unwrap().status(),StatusCode::OK);
 let(status,result)=json_response(app.clone().oneshot(remove(&a.token,id)).await.unwrap()).await;assert_eq!(status,StatusCode::OK);assert_eq!(result["fileReleased"],false);assert!(path.exists());let(_,list)=json_response(app.clone().oneshot(request("GET","/api/speech/model-library",Some(&a.token),Body::empty())).await.unwrap()).await;assert!(list["models"].as_array().unwrap().is_empty());assert_eq!(list["selectedId"],"configured");assert_eq!(app.clone().oneshot(select(&a.token,id)).await.unwrap().status(),StatusCode::NOT_FOUND);let(_,list)=json_response(app.clone().oneshot(request("GET","/api/speech/model-library",Some(&b.token),Body::empty())).await.unwrap()).await;assert_eq!(list["models"].as_array().unwrap().len(),1);
 let(status,result)=json_response(app.oneshot(remove(&b.token,id)).await.unwrap()).await;assert_eq!(status,StatusCode::OK);assert_eq!(result["fileReleased"],true);assert!(!path.exists());
}
async fn model_job(state:&video_kadr_backend::state::AppState,id:&str)->video_kadr_backend::model::Job{tokio::time::timeout(std::time::Duration::from_secs(30),async{loop{let job=state.get_job(id).await.unwrap().unwrap();if matches!(job.status,video_kadr_backend::model::JobStatus::Done|video_kadr_backend::model::JobStatus::Error|video_kadr_backend::model::JobStatus::Cancelled){break job}tokio::time::sleep(std::time::Duration::from_millis(20)).await;}}).await.unwrap()}
async fn gone(path:&std::path::Path){tokio::time::timeout(std::time::Duration::from_secs(5),async{while path.exists(){tokio::time::sleep(std::time::Duration::from_millis(20)).await;}}).await.expect("deferred model file release")}
#[tokio::test]#[ignore="requires explicit local Whisper model and public audio fixture"]async fn removed_model_finishes_queued_and_synchronous_work_before_release(){
 let data=std::fs::read(std::env::var("VIDEO_KADR_TEST_WHISPER_MODEL").unwrap()).unwrap();let audio=std::env::var("VIDEO_KADR_TEST_WHISPER_AUDIO").unwrap();let(state,_dir)=support::make_state(true,false).await;let owner=state.db.register_auth_user("delete-real-owner","model deletion password").await.unwrap().unwrap();let app=support::router(state.clone());let(_,installed)=json_response(app.clone().oneshot(request("PUT","/api/speech/model-library?name=Retained",Some(&owner.token),Body::from(data.clone()))).await.unwrap()).await;let id=installed["id"].as_str().unwrap();let path=state.storage.join("models/whisper").join(format!("{id}.bin"));assert_eq!(app.clone().oneshot(select(&owner.token,id)).await.unwrap().status(),StatusCode::OK);std::fs::copy(audio,state.sources_dir().join("retained.wav")).unwrap();assert!(state.library.add(video_kadr_backend::library::MediaEntry::from_result("source",&json!({"id":"retained","filename":"retained.wav","mediaType":"audio"}))).await);
 let speech_request=|uri:&str|{let mut r=request("POST",uri,Some(&owner.token),Body::from(json!({"sourceId":"retained","startUs":0,"endUs":11000000,"language":"en"}).to_string()));r.headers_mut().insert("content-type","application/json".parse().unwrap());r};
 let mut permits=vec![];for _ in 0..state.resource_limit(video_kadr_backend::config::resource_classes::ResourceClass::Analysis){permits.push(state.acquire_job_slot(video_kadr_backend::config::resource_classes::ResourceClass::Analysis).await.unwrap());}let(status,job)=json_response(app.clone().oneshot(speech_request("/api/speech/jobs")).await.unwrap()).await;assert_eq!(status,StatusCode::ACCEPTED);let(_,removed)=json_response(app.clone().oneshot(remove(&owner.token,id)).await.unwrap()).await;assert_eq!(removed["fileReleased"],false);assert!(path.exists());state.begin_shutdown();drop(permits);assert!(state.wait_for_tasks(std::time::Duration::from_secs(5)).await);let state=video_kadr_backend::state::AppState::new_with_runtime(state.storage.clone(),2,(*state.tools).clone(),video_kadr_backend::library::Library::load(state.storage.clone()).await,video_kadr_backend::db::Db::open(&state.storage).await.unwrap(),state.encode_budget,2).unwrap();state.recover_jobs().await;video_kadr_backend::handlers::resume_pending_jobs(&state).await;let app=support::router(state.clone());let done=model_job(&state,job["jobId"].as_str().unwrap()).await;assert_eq!(done.status,video_kadr_backend::model::JobStatus::Done,"{done:?}");assert_eq!(done.result.unwrap()["modelHash"],id);gone(&path).await;
 assert_eq!(app.clone().oneshot(request("PUT","/api/speech/model-library?name=Retained",Some(&owner.token),Body::from(data.clone()))).await.unwrap().status(),StatusCode::OK);assert_eq!(app.clone().oneshot(select(&owner.token,id)).await.unwrap().status(),StatusCode::OK);let mut permits=vec![];for _ in 0..state.resource_limit(video_kadr_backend::config::resource_classes::ResourceClass::Analysis){permits.push(state.acquire_job_slot(video_kadr_backend::config::resource_classes::ResourceClass::Analysis).await.unwrap());}let running=tokio::spawn(app.clone().oneshot(speech_request("/api/speech/transcribe")));
 tokio::time::timeout(std::time::Duration::from_secs(30),async{loop{let(_,list)=json_response(app.clone().oneshot(request("GET","/api/speech/model-library",Some(&owner.token),Body::empty())).await.unwrap()).await;if list["models"][0]["inUse"]==true{break}tokio::time::sleep(std::time::Duration::from_millis(20)).await;}}).await.unwrap();let(_,removed)=json_response(app.clone().oneshot(remove(&owner.token,id)).await.unwrap()).await;assert_eq!(removed["fileReleased"],false);assert!(path.exists());drop(permits);let(status,result)=json_response(running.await.unwrap().unwrap()).await;assert_eq!(status,StatusCode::OK,"{result}");assert_eq!(result["modelHash"],id);gone(&path).await;
 assert_eq!(app.clone().oneshot(request("PUT","/api/speech/model-library?name=Retained",Some(&owner.token),Body::from(data))).await.unwrap().status(),StatusCode::OK);assert_eq!(app.clone().oneshot(select(&owner.token,id)).await.unwrap().status(),StatusCode::OK);let mut permits=vec![];for _ in 0..state.resource_limit(video_kadr_backend::config::resource_classes::ResourceClass::Analysis){permits.push(state.acquire_job_slot(video_kadr_backend::config::resource_classes::ResourceClass::Analysis).await.unwrap());}let(_,job)=json_response(app.clone().oneshot(speech_request("/api/speech/jobs")).await.unwrap()).await;assert_eq!(app.clone().oneshot(remove(&owner.token,id)).await.unwrap().status(),StatusCode::OK);let cancel=request("POST",&format!("/api/jobs/{}/cancel",job["jobId"].as_str().unwrap()),Some(&owner.token),Body::empty());assert_eq!(app.oneshot(cancel).await.unwrap().status(),StatusCode::OK);drop(permits);assert_eq!(model_job(&state,job["jobId"].as_str().unwrap()).await.status,video_kadr_backend::model::JobStatus::Cancelled);gone(&path).await;state.begin_shutdown();assert!(state.wait_for_tasks(std::time::Duration::from_secs(5)).await);
}
